using System.Security.Claims;
using System.ComponentModel.DataAnnotations;
using CafeManagement.Api.Contracts;
using CafeManagement.Api.Domain;
using CafeManagement.Api.Infrastructure.Persistence;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;
namespace CafeManagement.Api.Application;
public sealed class CustomerService(IDbContextFactory<CafeDbContext> factory,IServiceScopeFactory scopes,OrderService orders)
{
 public async Task<string?> UserIdAsync(ClaimsPrincipal principal){if(principal.Identity?.IsAuthenticated!=true)return null;await using var scope=scopes.CreateAsyncScope();var users=scope.ServiceProvider.GetRequiredService<UserManager<IdentityUser>>();var user=await users.GetUserAsync(principal);var opt=scope.ServiceProvider.GetRequiredService<IOptions<IdentityOptions>>().Value;if(user is null||principal.FindFirstValue(opt.ClaimsIdentity.SecurityStampClaimType)!=await users.GetSecurityStampAsync(user)||await users.IsInRoleAsync(user,"Admin")||await users.IsInRoleAsync(user,"Cashier"))return null;return user.Id;}
 public async Task<CustomerProfile?> ProfileAsync(ClaimsPrincipal principal){var id=await UserIdAsync(principal);if(id is null)return null;await using var db=await factory.CreateDbContextAsync();return await db.CustomerProfiles.AsNoTracking().SingleOrDefaultAsync(p=>p.UserId==id);}
 public async Task<bool> SaveProfileAsync(ClaimsPrincipal principal,CustomerProfileInput input){if(!Validator.TryValidateObject(input,new ValidationContext(input),new List<ValidationResult>(),true)||string.IsNullOrWhiteSpace(input.DisplayName)||string.IsNullOrWhiteSpace(input.Phone))return false;var id=await UserIdAsync(principal);if(id is null)return false;await using var db=await factory.CreateDbContextAsync();var profile=await db.CustomerProfiles.SingleOrDefaultAsync(p=>p.UserId==id);if(profile is null)return false;try{var version=Convert.FromBase64String(input.RowVersion);if(!profile.RowVersion.SequenceEqual(version))return false;profile.DisplayName=input.DisplayName.Trim();profile.Phone=input.Phone.Trim();profile.Address=string.IsNullOrWhiteSpace(input.Address)?null:input.Address.Trim();await db.SaveChangesAsync();return true;}catch(FormatException){return false;}catch(DbUpdateConcurrencyException){return false;}}
 public async Task<OrderTracking[]> OrdersAsync(ClaimsPrincipal principal){var id=await UserIdAsync(principal);if(id is null)return [];await using var db=await factory.CreateDbContextAsync();return (await db.Orders.AsNoTracking().Include(o=>o.Lines).Where(o=>o.CustomerUserId==id&&o.Origin==OrderOrigin.Customer).OrderByDescending(o=>o.CreatedAtUtc).Take(100).ToArrayAsync()).Select(OrderService.Project).ToArray();}
 public async Task<CustomerOrderDetails?> OrderAsync(ClaimsPrincipal principal,Guid reference){var id=await UserIdAsync(principal);if(id is null)return null;await using var db=await factory.CreateDbContextAsync();var order=await db.Orders.AsNoTracking().Include(o=>o.Lines).SingleOrDefaultAsync(o=>o.Reference==reference&&o.CustomerUserId==id&&o.Origin==OrderOrigin.Customer);if(order is null)return null;var payment=await db.PaymentSettlements.AsNoTracking().SingleOrDefaultAsync(p=>p.OrderId==order.Id);return new(OrderService.Project(order),order.DeliveryAddress,payment?.Method=="Cash"?"Paid in cash":"Cash payment due");}
 public async Task<OrderPlacementOutcome> PlaceAsync(ClaimsPrincipal principal,string? capability,OrderPlacementInput input,CancellationToken ct=default){if(principal.Identity?.IsAuthenticated!=true)return await orders.PlaceAsync(capability,input,ct);var id=await UserIdAsync(principal);return id is null?new(null,new(OperationErrorKind.Forbidden,"Use a customer account or sign out to order as a guest.")):await orders.PlaceCustomerAsync(capability,input,id,ct);}
}
